package net.minecraft.world.phys;
public class AABB {public double x0,y0,z0,x1,y1,z1;public AABB(double a,double b,double c,double d,double e,double f){x0=a;y0=b;z0=c;x1=d;y1=e;z1=f;}public java.util.Optional<Vec3> clip(Vec3 a,Vec3 b){double near=0,far=1;double[] s={a.x,a.y,a.z},d={b.x-a.x,b.y-a.y,b.z-a.z},lo={x0,y0,z0},hi={x1,y1,z1};for(int i=0;i<3;i++){if(Math.abs(d[i])<1e-9){if(s[i]<lo[i]||s[i]>hi[i])return java.util.Optional.empty();}else{double p=(lo[i]-s[i])/d[i],q=(hi[i]-s[i])/d[i];near=Math.max(near,Math.min(p,q));far=Math.min(far,Math.max(p,q));if(near>far)return java.util.Optional.empty();}}return java.util.Optional.of(a.add(b.subtract(a).scale(near)));}public Vec3 getCenter(){return new Vec3((x0+x1)/2,(y0+y1)/2,(z0+z1)/2);}public AABB move(double a,double b,double c){return new AABB(x0+a,y0+b,z0+c,x1+a,y1+b,z1+c);}public AABB inflate(double d){return new AABB(x0-d,y0-d,z0-d,x1+d,y1+d,z1+d);}public AABB expandTowards(Vec3 d){return new AABB(x0+Math.min(0,d.x),y0+Math.min(0,d.y),z0+Math.min(0,d.z),x1+Math.max(0,d.x),y1+Math.max(0,d.y),z1+Math.max(0,d.z));}public static AABB ofSize(Vec3 p,double a,double b,double c){return new AABB(p.x-a/2,p.y-b/2,p.z-c/2,p.x+a/2,p.y+b/2,p.z+c/2);}}
